401							AND client_id = ${bindingIdentity.clientId}
402							AND user_id = ${bindingIdentity.userId}
403							AND conversation_key = ${bindingIdentity.conversationKey}
404							AND expires_at > now()
405						ORDER BY updated_at DESC, tool_call_key
406						LIMIT ${MCP_APP_RESULT_CONVERSATION_CAP}
407						FOR UPDATE
408					`;
409					const row = candidates.find((candidate) => {
410						const snapshot = parseSnapshot(candidate.body);
411						return snapshot?.bindingKey === bindingIdentity.toolCallKey;
412					});
